SELECT
    e.*,
    v.license_plate AS vehicle_plate
FROM sys_vehicle_expense e
LEFT JOIN sys_vehicle v ON v.vehicle_id = e.vehicle_id



            AND e.vehicle_id = #{query.vehicleId}


            AND e.usage_id = #{query.usageId}


            AND e.expense_type = #{query.expenseType}



        AND e.expense_date >= #{startDate}


        AND e.expense_date <= #{endDate}


ORDER BY e.expense_date DESC, e.expense_id DESC

SELECT COALESCE(SUM(amount), 0) AS totalAmount, COUNT(*) AS count, COALESCE(SUM(CASE WHEN expense_date >= DATE_FORMAT(CURDATE(), '%Y-%m-01') THEN amount ELSE 0 END), 0) AS monthlyAmount, COALESCE(SUM(CASE WHEN expense_date >= DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 1 MONTH), '%Y-%m-01') AND expense_date < DATE_FORMAT(CURDATE(), '%Y-%m-01') THEN amount ELSE 0 END), 0) AS lastMonthAmount FROM sys_vehicle_expense
expense_date >= #{startDate}
AND expense_date <= #{endDate}

SELECT expense_type AS expenseType, COALESCE(SUM(amount), 0) AS amount
FROM sys_vehicle_expense


        expense_date >= #{startDate}


        AND
        expense_date <= #{endDate}


GROUP BY expense_type
